body { font: 1rem/1.5 system-ui, sans-serif; color: #1e293b; background: white; }
body.contraste-eleve { color: white; background: #0f172a; }
button:focus-visible { outline: 3px solid #f59e0b; outline-offset: 3px; }

"use strict";
const bouton = document.querySelector("#theme-toggle");
bouton.addEventListener("click", () => {
  const actif = document.body.classList.toggle("contraste-eleve");
  bouton.setAttribute("aria-pressed", String(actif));
  bouton.textContent = actif ? "Désactiver le contraste" : "Activer le contraste";
});
